import{_ as t,o as a,c as r,a5 as d}from"./chunks/framework.CslsFoWx.js";const s="/VendoraSystem-docs/assets/01-recherche.BNxxSJfn.webp",o="/VendoraSystem-docs/assets/01-recherche.en.GgbnK5M-.webp",n="/VendoraSystem-docs/assets/01-recherche.ar.D08PXoMR.webp",i="/VendoraSystem-docs/assets/05-invite.PoFKkuGT.webp",c="/VendoraSystem-docs/assets/05-invite.en.BWZQVk7u.webp",l="/VendoraSystem-docs/assets/05-invite.ar.BccJxGxW.webp",u="/VendoraSystem-docs/assets/01-encaissement.asFsJ-zW.webp",p="/VendoraSystem-docs/assets/01-encaissement.en.BJUNwi2i.webp",m="/VendoraSystem-docs/assets/01-encaissement.ar.CHSwGn45.webp",g="/VendoraSystem-docs/assets/01-sur-place-ou-a-emporter.BMk4wR4I.webp",h="/VendoraSystem-docs/assets/01-sur-place-ou-a-emporter.en.B3R2IW6i.webp",b="/VendoraSystem-docs/assets/01-sur-place-ou-a-emporter.ar.Dfd5X2wB.webp",f="/VendoraSystem-docs/assets/03-android-panier.B-Lk8pt_.webp",_="/VendoraSystem-docs/assets/03-android-panier.en.CnHhI862.webp",v="/VendoraSystem-docs/assets/03-android-panier.ar.CstLyehJ.webp",N=JSON.parse(`{"title":"Centre d'aide : relecture humaine de l'anglais et de l'arabe, captures par langue (08-09/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-aide-relecture-langues.md","filePath":"generated/preuves/2026-11-08-aide-relecture-langues.md","lastUpdated":null}`),S={name:"preuves/2026-11-08-aide-relecture-langues.md"};function A(x,e,q,y,R,k){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="centre-d-aide-relecture-humaine-de-l-anglais-et-de-l-arabe-captures-par-langue-08-09-11-2026" tabindex="-1">Centre d&#39;aide : relecture humaine de l&#39;anglais et de l&#39;arabe, captures par langue (08-09/11/2026) <a class="header-anchor" href="#centre-d-aide-relecture-humaine-de-l-anglais-et-de-l-arabe-captures-par-langue-08-09-11-2026" aria-label="Permalink to &quot;Centre d&#39;aide : relecture humaine de l&#39;anglais et de l&#39;arabe, captures par langue (08-09/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-aide-relecture-langues</code> · 0 image(s) · 0 trace(s)</p><div><p>Carte Trello « P3 · Centre d&#39;aide : relecture humaine de l&#39;arabe et de l&#39;anglais, captures par langue ».</p><h2 id="_1-relecture-complete-en-ar-153-pages-par-langue" tabindex="-1">1. Relecture complète EN / AR (153 pages par langue) <a class="header-anchor" href="#_1-relecture-complete-en-ar-153-pages-par-langue" aria-label="Permalink to &quot;1. Relecture complète EN / AR (153 pages par langue)&quot;">​</a></h2><p>Toutes les pages <code>help/en/**</code> et <code>help/ar/**</code> ont été relues face à la page française (exactitude, naturel, terminologie du produit, anglais américain, arabe standard moderne, RTL). Pages modifiées : environ 140 en anglais, 145 en arabe (seuls quelques index étaient corrects).</p><p>Fautes types corrigées (avant → après) :</p><table tabindex="0"><thead><tr><th>Langue</th><th>Avant</th><th>Après</th><th>Nature</th></tr></thead><tbody><tr><td>EN</td><td>badge turns to <strong>Hors ligne</strong> (Offline) … <strong>Synchroniser maintenant</strong></td><td><strong>Offline</strong> … <strong>Sync now</strong></td><td>libellé d&#39;app laissé en français</td></tr><tr><td>EN</td><td><code>message=&quot;Rôle Manager requis&quot;</code> + « (displayed in French) »</td><td><code>message=&quot;Manager role required&quot;</code></td><td>message en réalité traduit par le produit</td></tr><tr><td>EN</td><td>cancelled, recognised, catalogue, back-office, till</td><td>canceled, recognized, catalog, back office, register</td><td>anglais américain, glossaire</td></tr><tr><td>EN</td><td>« A single row in error is enough for nothing to be applied »</td><td>« If even one row has an error, nothing is applied »</td><td>calque du français</td></tr><tr><td>EN/AR</td><td>tableau des colonnes CSV sans <code>soldByWeight</code>, <code>scaleCode</code>, <code>trackExpiry</code>, <code>expiryAlertDays</code></td><td>colonnes ajoutées (et page FR corrigée)</td><td>contenu manquant / faux</td></tr><tr><td>AR</td><td>« المكتب الخلفي » (≈ 450 occurrences)</td><td>« لوحة الإدارة » (libellé du produit)</td><td>terminologie</td></tr><tr><td>AR</td><td>« قائمة الصندوق »، « الصندوق الرئيسي »</td><td>« قائمة نقطة البيع »، « نقطة البيع الرئيسية »</td><td>règle « caisse »</td></tr><tr><td>AR</td><td>« وتُضاف نقاط البيع إلى رصيده » (fidélité)</td><td>« وتُضاف النقاط المكتسبة من هذا البيع إلى رصيده »</td><td>contresens</td></tr><tr><td>AR</td><td>« لا تخطيط لهذا المتجر »</td><td>« لا شاشة بيع لهذا المتجر »</td><td>ancien terme « layout »</td></tr><tr><td>AR</td><td>« Reçu » (bon de commande) = « الوصل »</td><td>« مستلم »</td><td>faux sens</td></tr></tbody></table><h2 id="_2-le-mot-arabe-pour-«-caisse-»" tabindex="-1">2. Le mot arabe pour « caisse » <a class="header-anchor" href="#_2-le-mot-arabe-pour-«-caisse-»" aria-label="Permalink to &quot;2. Le mot arabe pour « caisse »&quot;">​</a></h2><p>Inventaire : « صندوق » (apps 65, back-office 72) et « نقطة البيع » (back-office 48, aide 541) pour le même sens. Règle documentée dans <a href="./../../../help/tools/GLOSSAIRE"><code>help/tools/GLOSSAIRE.md</code></a> : <strong>l&#39;appareil</strong> = « نقطة البيع » (« نقطة البيع الرئيسية »، « قائمة نقطة البيع »، « على نقطة البيع هذه ») ; <strong>l&#39;argent, le tiroir, la session, le comptoir</strong> = « الصندوق » (« جلسة الصندوق »، « فارق الصندوق »، « أمين الصندوق »، « ادفع عند الصندوق »). Appliquée au back-office (<code>ar.ts</code> : 162 valeurs, dont appairage « اقتران », encaissement « التحصيل », écran de vente « شاشة البيع », client « الحريف », catégorie « الصنف »), aux apps (<code>CaisseStrings.kt</code>, <code>AppStrings.kt</code>, borne : 108 valeurs, dont « الكشك » pour la borne, « رمز PIN لمدير », accord du nombre d&#39;essais PIN) et à l&#39;aide.</p><h2 id="_3-derniers-textes-en-francais-dans-le-produit" tabindex="-1">3. Derniers textes en français dans le produit <a class="header-anchor" href="#_3-derniers-textes-en-francais-dans-le-produit" aria-label="Permalink to &quot;3. Derniers textes en français dans le produit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Texte</th><th>Avant (EN / AR)</th><th>Après</th></tr></thead><tbody><tr><td>Bandeau d&#39;abonnement des apps (<code>TenantStatusState.banner</code>)</td><td>message français du serveur</td><td><code>CaisseAccountTexts</code> fr / en / ar ; le serveur envoie les dates formatées (<code>cancelDate</code>, <code>exportUntilDate</code>)</td></tr><tr><td>Refus d&#39;envoi durables (<code>PushRefusal.label</code>)</td><td>français</td><td><code>label(k)</code> : « Register revoked in the back office… » / « أُبطلت نقطة البيع هذه… »</td></tr><tr><td>Mise à jour requise (<code>AppVersion</code>)</td><td>français</td><td><code>localizeUpgradeMessage</code> : « Update required: minimum version 1.3.0… »</td></tr><tr><td>Lien « Serveur personnalisé » (appairage, iOS + Android)</td><td>en dur</td><td><code>settings.customServer</code></td></tr><tr><td>« 1 choix obligatoire » (iOS : commande, formule, borne)</td><td><code>ModifierRules.hint</code> (FR)</td><td><code>tablet.modifierHint</code> (parité Android)</td></tr><tr><td>Accueil de la borne iOS</td><td>français jusqu&#39;au choix de langue</td><td>langue de l&#39;appareil dès l&#39;accueil</td></tr><tr><td>Détail de rapprochement d&#39;un retour (back-office)</td><td>« retour … : 2500 remboursés en caisse, 1000 confirmés… »</td><td>gabarits <code>web/src/app/core/api/server-message-templates.ts</code> : « Return 5f1c2a9e: 25,00 € refunded at the register, 10,00 € confirmed by the provider »</td></tr><tr><td>« Import appliqué : … » (import CSV)</td><td>français</td><td>gabarit traduit</td></tr><tr><td>Messages de rôle (« MANAGER role required », « OWNER »)</td><td>codes bruts</td><td>« Manager role required », « دور المدير مطلوب » ; clés ajoutées (exports comptables, clés d&#39;API, magasin source)</td></tr><tr><td>Flèche retour « ← » (Android, diagnostic et file d&#39;impression)</td><td>caractère figé, faux en arabe</td><td>icône <code>ArrowBack</code> (miroir RTL)</td></tr></tbody></table><h2 id="_4-pages-fr-alignees-sur-le-produit" tabindex="-1">4. Pages FR alignées sur le produit <a class="header-anchor" href="#_4-pages-fr-alignees-sur-le-produit" aria-label="Permalink to &quot;4. Pages FR alignées sur le produit&quot;">​</a></h2><p>« layout de vente » → « écran de vente » ; « l&#39;owner » → « le propriétaire » (aussi dans le produit : remises, fidélité, ticket, politique de vente, clé LAN, sécurité des caisses, serveur) ; « gérant » / « PIN de gérant » → « manager » / « PIN d&#39;un manager » (aussi dans le produit : bornes, péremption, appareils, transferts, invitation, inventaire) ; rôles de l&#39;écran de démo « Kiosque / Terminal serveur » → « Borne / Téléphone de salle » ; réglages des presets (Apparence › Kiosque), export CSV (vente au poids exportée), zones des téléphones et postes des écrans cuisine (pages Restaurant, pas la fiche de l&#39;appareil), « e-mail ».</p><h2 id="_5-captures-par-langue" tabindex="-1">5. Captures par langue <a class="header-anchor" href="#_5-captures-par-langue" aria-label="Permalink to &quot;5. Captures par langue&quot;">​</a></h2><p><code>&lt;Capture&gt;</code> choisit <code>NN-nom.en.webp</code> / <code>NN-nom.ar.webp</code> sur les pages de la langue ; l&#39;encadré « captures en français » disparaît des pages entièrement couvertes (10 pages par langue aujourd&#39;hui). <code>coverage:strict</code> vert : « en 75 capture(s), 10/136 page(s) entièrement couvertes · ar 75 … ».</p><table tabindex="0"><thead><tr><th>Surface</th><th>Pages</th><th>Outil</th></tr></thead><tbody><tr><td>Back-office</td><td>tableau de bord, liste des produits, import CSV, appairer un appareil, équipe, rapports de ventes</td><td><code>capture.mjs --langue en|ar</code></td></tr><tr><td>iOS</td><td>ouvrir la caisse, faire une vente, encaisser ; téléphone : plan de salle, prendre la commande ; borne : accueil et catalogue</td><td>pilote XCUITest, simulateurs dédiés (supprimés)</td></tr><tr><td>Android</td><td>faire une vente, encaisser (emulator-5554) ; menu du téléphone, encaisser à la table (emulator-5556)</td><td><code>drv.py</code>, APK du worktree</td></tr></tbody></table><p>Exemples :</p><table tabindex="0"><thead><tr><th>Français</th><th>Anglais</th><th>Arabe</th></tr></thead><tbody><tr><td><img src="'+s+'" alt=""></td><td><img src="'+o+'" alt=""></td><td><img src="'+n+'" alt=""></td></tr><tr><td><img src="'+i+'" alt=""></td><td><img src="'+c+'" alt=""></td><td><img src="'+l+'" alt=""></td></tr><tr><td><img src="'+u+'" alt=""></td><td><img src="'+p+'" alt=""></td><td><img src="'+m+'" alt=""></td></tr><tr><td><img src="'+g+'" alt=""></td><td><img src="'+h+'" alt=""></td><td><img src="'+b+'" alt=""></td></tr><tr><td><img src="'+f+'" alt=""></td><td><img src="'+_+'" alt=""></td><td><img src="'+v+'" alt=""></td></tr></tbody></table><h2 id="restes-connus" tabindex="-1">Restes connus <a class="header-anchor" href="#restes-connus" aria-label="Permalink to &quot;Restes connus&quot;">​</a></h2><ul><li>Nom de marque par défaut « Caisse » (thème sans nom, iOS <code>ThemeStore.nomParDefaut</code>, Android <code>ThemeHolder.DEFAULT_NAME</code>) non traduit ; feuille « Ouvrir la session » iOS et montants rapides non mis en miroir en arabe ; montants au format français en anglais ; valeurs par défaut « Chèque », « Bon d&#39;achat » du paiement « Autre ».</li><li>Messages serveur encore français sans traduction (raisons de rejet de synchro, objets d&#39;e-mails, messages des transferts / FEC / délégations…) : cités en français avec leur traduction dans l&#39;aide.</li><li>Captures par langue des autres pages (126 / 136) : à produire au fil des lots avec les mêmes outils.</li></ul></div>',3)])])}const P=t(S,[["render",A]]);export{N as __pageData,P as default};
